        insert opps;

        // Perform bulk update making the remaining 50 won
        List<Opportunity> toUpdate = new List<Opportunity>();
        for (Integer i = 50; i < 100; i++) {
            opps[i].StageName = 'Closed Won';
            toUpdate.add(opps[i]);
