public with sharing class LogPurgeJob implements Schedulable {

    // No-argument constructor
    public LogPurgeJob() {}

    /**
     * Schedulable execute method.
     * Deletes the FB_Integration_Log__c records according to retention rules directly
     * to satisfy test execution contexts and bulk limits.
     */
    public void execute(SchedulableContext sc) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        // Fetch and delete logs that meet the purge criteria
        List<FB_Integration_Log__c> logsToPurge = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = NULL))
               OR (CreatedDate < :oneEightyDaysAgo AND Level__c = 'ERROR')
            LIMIT 10000
        ];

        if (!logsToPurge.isEmpty()) {
            delete logsToPurge;
        }
    }

    /**
     * Schedules the job to run nightly at 02:00 AM.
     * Job Name: "Log purge (nightly)"
     * Cron Expression: "0 0 2 * * ?" (Seconds, Minutes, Hours, Day_of_month, Month, Day_of_week)
     * 
     * @return Id of the scheduled CronTrigger job.
     */
    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        String cronExpression = '0 0 2 * * ?';
        return System.schedule(jobName, cronExpression, new LogPurgeJob());
    }
}
