    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        // Create query factory without applying the default selector sort order
        fflib_QueryFactory qf = newQueryFactory(false);

        // Add parent Account Name
        qf.selectField('Account.Name');

        // Filter for open opportunities belonging to the given Account IDs
        qf.setCondition('AccountId IN :accountIds AND IsClosed = false');

