public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    // Constructor to support enqueueing a single Case
    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    // Constructor to support bulk distribution buckets
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Query the cases in this batch to retrieve CaseNumber and ContactId
        List<Case> cases = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds];
        List<Task> tasksToInsert = new List<Task>();

        for (Case c : cases) {
            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            // Use Database.insert with allOrNone=false to ensure one case's failure
            // does not affect task creation for other cases in the same execution context.
            Database.insert(tasksToInsert, false);
        }
    }
}
