import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    @track _processedOptions = [];
    _selectedValue = '';

    activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this.processOptions();
        this.syncActiveIndexToValue();
    }

    @api
    get value() {
        return this._selectedValue;
    }
    set value(val) {
        this._selectedValue = val;
        this.processOptions();
        this.syncActiveIndexToValue();
    }

    processOptions() {
        this._processedOptions = this._options.map((opt, index) => {
            const isSelected = opt.value === this._selectedValue;
            return {
                value: opt.value,
                label: opt.label,
                id: `option-${index}`,
                ariaSelected: isSelected ? 'true' : 'false'
            };
        });
    }

    syncActiveIndexToValue() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._selectedValue);
        if (index !== -1) {
            this.activeIndex = index;
        } else {
            this.activeIndex = 0;
        }
    }

    get activeDescendantId() {
        if (this._processedOptions.length > 0 && this.activeIndex >= 0 && this.activeIndex < this._processedOptions.length) {
            return this._processedOptions[this.activeIndex].id;
        }
        return undefined;
    }

    get formattedOptions() {
        const activeId = this.activeDescendantId;
        return this._processedOptions.map((opt) => {
            const isActive = opt.id === activeId;
            let cssClass = 'slds-media slds-listbox__option slds-listbox__option_plain';
            if (opt.ariaSelected === 'true') {
                cssClass += ' slds-is-selected';
            }
            if (isActive) {
                cssClass += ' slds-has-focus';
            }
            return {
                ...opt,
                class: cssClass,
                isAriaSelectedTrue: opt.ariaSelected === 'true'
            };
        });
    }

    handleKeyDown(event) {
        const key = event.key;
        const maxIndex = this._options.length - 1;
        if (maxIndex < 0) {
            return;
        }

        let preventDefault = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < maxIndex) {
                    this.activeIndex++;
                }
                preventDefault = true;
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                preventDefault = true;
                break;
            case 'Home':
                this.activeIndex = 0;
                preventDefault = true;
                break;
            case 'End':
                this.activeIndex = maxIndex;
                preventDefault = true;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeIndex);
                preventDefault = true;
                break;
            default:
                break;
        }

        if (preventDefault) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex(opt => opt.value === clickedValue);
        if (index !== -1) {
            this.activeIndex = index;
            this.selectOption(index);
        }
    }

    selectOption(index) {
        if (index >= 0 && index < this._options.length) {
            const selectedOption = this._options[index];
            if (selectedOption.value !== this._selectedValue) {
                this.dispatchEvent(new CustomEvent('change', {
                    detail: { value: selectedOption.value }
                }));
            }
        }
    }
}
