public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        validateEmailUniqueness((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validateEmailUniqueness((List<Contact>) triggerNew, new Map<Id, Contact>((List<Contact>) triggerOld));
    }

    private void validateEmailUniqueness(List<Contact> triggerNew, Map<Id, Contact> triggerOldMap) {
        List<Contact> contactsToProcess = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : triggerNew) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            if (triggerOldMap != null) {
                Contact oldC = triggerOldMap.get(c.Id);
                if (oldC != null && c.Email == oldC.Email && c.AccountId == oldC.AccountId) {
                    continue;
                }
            }

            contactsToProcess.add(c);
            accountIds.add(c.AccountId);
            emails.add(c.Email.toLowerCase());
        }

        if (contactsToProcess.isEmpty()) {
            return;
        }

        Map<Id, Set<String>> existingAccountEmails = new Map<Id, Set<String>>();
        Set<Id> currentBatchIds = new Set<Id>();
        if (triggerOldMap != null) {
            currentBatchIds.addAll(triggerOldMap.keySet());
        }

        for (Contact c : [
            SELECT Id, AccountId, Email 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email IN :emails
            AND Id NOT IN :currentBatchIds
        ]) {
            Id accId = c.AccountId;
            String emailLower = c.Email.toLowerCase();

            if (!existingAccountEmails.containsKey(accId)) {
                existingAccountEmails.put(accId, new Set<String>());
            }
            existingAccountEmails.get(accId).add(emailLower);
        }

        Set<String> processedKeys = new Set<String>();

        for (Contact c : contactsToProcess) {
            Id accId = c.AccountId;
            String emailLower = c.Email.toLowerCase();
            String compositeKey = accId + '-' + emailLower;

            if (processedKeys.contains(compositeKey)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

            Set<String> accEmails = existingAccountEmails.get(accId);
            if (accEmails != null && accEmails.contains(emailLower)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

            processedKeys.add(compositeKey);
        }
    }
}
